/**
 * @method
 * @name scwin.setInsurInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setInsurInfo = function () {
    /* sdd-asis-lifecycle:begin setInsurInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($("td#std_cd_apct_tp_cd input:checked").val() === "1") {
        $c.util.getComponent('ipt_applComNm').setValue(($c.util.getComponent("ipt_comNm").getValue() || ''));
        $c.util.getComponent('ipt_apctNm').setValue('' + dma_companyInfoVO.get("chrgNm") + '');
        const apct_tel_no = '' + dma_companyInfoVO.get("chrgTelNo") + '';
        const apct_fax_no = '' + dma_companyInfoVO.get("chrgFaxNo") + '';
        const encryp_apct_email = '' + dma_companyInfoVO.get("chrgEmail") + '';
        const apct_hp_no = '' + dma_companyInfoVO.get("chrgCellphone") + '';
        if (apct_tel_no != null && apct_tel_no !== '') {
            const apct_tel_no_arr = apct_tel_no.split('-');
            const apct_tel_no_arr_size = apct_tel_no.match(/-/g).length;
            if (apct_tel_no_arr_size > 1) {
                if (apct_tel_no_arr[0] === "00") {
                    $c.util.getComponent('ipt_apctTelNo1').setValue('');
                } else {
                    $c.util.getComponent('ipt_apctTelNo1').setValue(apct_tel_no_arr[0]);
                }
                $c.util.getComponent('ipt_apctTelNo2').setValue(apct_tel_no_arr[1]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(apct_tel_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue('');
                $c.util.getComponent('ipt_apctTelNo2').setValue(apct_tel_no_arr[0]);
                $c.util.getComponent('ipt_apctTelNo3').setValue(apct_tel_no_arr[1]);
            }
        }
        $c.util.getComponent('ipt_apctInnrNo').setValue('' + dma_companyInfoVO.get("chrgInnrNo") + '');
        if (apct_fax_no != null && apct_fax_no !== '') {
            const apct_fax_no_arr = apct_fax_no.split('-');
            const apct_fax_no_arr_size = apct_fax_no.match(/-/g).length;
            if (apct_fax_no_arr_size > 1) {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(apct_fax_no_arr[0]);
                $c.util.getComponent('ipt_apctFaxNo2').setValue(apct_fax_no_arr[1]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(apct_fax_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue('');
                $c.util.getComponent('ipt_apctFaxNo2').setValue(apct_fax_no_arr[0]);
                $c.util.getComponent('ipt_apctFaxNo3').setValue(apct_fax_no_arr[1]);
            }
        }
        if (apct_hp_no != null && apct_hp_no !== '') {
            const apct_hp_no_arr = apct_hp_no.split('-');
            const apct_hp_no_arr_size = apct_hp_no.match(/-/g).length;
            if (apct_hp_no_arr_size > 1) {
                $c.util.getComponent('ipt_apctHpNo1').setValue(apct_hp_no_arr[0]);
                $c.util.getComponent('ipt_apctHpNo2').setValue(apct_hp_no_arr[1]);
                $c.util.getComponent('ipt_apctHpNo3').setValue(apct_hp_no_arr[2]);
            } else {
                $c.util.getComponent('ipt_apctHpNo1').setValue('');
                $c.util.getComponent('ipt_apctHpNo2').setValue(apct_hp_no_arr[0]);
                $c.util.getComponent('ipt_apctHpNo3').setValue(apct_hp_no_arr[1]);
            }
        }
        if (encryp_apct_email != null && encryp_apct_email !== '') {
            const encryp_apct_email_arr = encryp_apct_email.split('@');
            if (encryp_apct_email_arr.length < 2) {
                $c.util.getComponent('ipt_encrypApctEmail1').setValue(encryp_apct_email_arr[0]);
            } else {
                $c.util.getComponent('ipt_encrypApctEmail1').setValue(encryp_apct_email_arr[0]);
                $c.util.getComponent('ipt_encrypApctEmail2').setValue(encryp_apct_email_arr[1]);
            }
        }
    } else {
        $c.util.getComponent('ipt_applComNm').setValue("");
        $c.util.getComponent('ipt_apctNm').setValue("");
        $c.util.getComponent('ipt_encrypApctEmail1').setValue("");
        $c.util.getComponent('ipt_encrypApctEmail2').setValue("");
        $c.util.getComponent('ipt_apctTelNo1').setValue("");
        $c.util.getComponent('ipt_apctTelNo2').setValue("");
        $c.util.getComponent('ipt_apctTelNo3').setValue("");
        $c.util.getComponent('ipt_apctInnrNo').setValue("");
        $c.util.getComponent('ipt_apctFaxNo1').setValue("");
        $c.util.getComponent('ipt_apctFaxNo2').setValue("");
        $c.util.getComponent('ipt_apctFaxNo3').setValue("");
        $c.util.getComponent('ipt_apctHpNo1').setValue("");
        $c.util.getComponent('ipt_apctHpNo2').setValue("");
        $c.util.getComponent('ipt_apctHpNo3').setValue("");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.Chk_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.Chk_form = async function () {
    /* sdd-asis-lifecycle:begin Chk_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const thisForm = $('#JLDINF10500');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    if ($c.util.getComponent('ipt_fisnMakeYn').getValue() !== 'Y') {
        await $c.win.alert("[FISN생성] 버튼으로 'FISN'을 확인하세요.");
        $c.util.getComponent("ipt_fisnVal").focus();
        return;
    }
    let apct_tel_no = $c.util.getComponent('ipt_apctTelNo1').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo2').getValue() + "-" + $c.util.getComponent('ipt_apctTelNo3').getValue(); if (apct_tel_no == null) { apct_tel_no = ''; }
    let apct_fax_no = $c.util.getComponent('ipt_apctFaxNo1').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo2').getValue() + "-" + $c.util.getComponent('ipt_apctFaxNo3').getValue(); if (apct_fax_no == null) { apct_fax_no = ''; }
    let apct_hp_no = $c.util.getComponent('ipt_apctHpNo1').getValue() + "-" + $c.util.getComponent('ipt_apctHpNo2').getValue() + "-" + $c.util.getComponent('ipt_apctHpNo3').getValue(); if (apct_hp_no == null) { apct_hp_no = ''; }
    let encryp_apct_email = $c.util.getComponent('ipt_encrypApctEmail1').getValue() + "@" + $c.util.getComponent('ipt_encrypApctEmail2').getValue(); if (encryp_apct_email == null) { encryp_apct_email = ''; }
    if (apct_fax_no === "--") {
        apct_fax_no = "";
    }
    $c.util.getComponent('ipt_apctTelNo').setValue(apct_tel_no);
    $c.util.getComponent('ipt_apctFaxNo').setValue(apct_fax_no);
    $c.util.getComponent('ipt_encrypCellphoneNo').setValue(apct_hp_no);
    $c.util.getComponent('ipt_encrypApctEmail').setValue(encryp_apct_email);
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return;
    }
    if ($c.util.getComponent('ipt_stdCdGrntFeeApplYn').getValue() === 'Y') {
        const fm = (document.JLDINF10500 || { elements: [] });
        const width = 800;
