                    $c.num.formatNumber($('#ipt_expPayAmt')[0]);
                }
                $c.util.getComponent('cal_isuDd').setValue($c.date.dateFormat(jsonData.isu_dd));
                $c.util.getComponent('ipt_dcSales').setValue(jsonData.dc_sales);
                if (jsonData.dc_sales != null) {
                    (($c.util.getComponent('txt_dcSalesMoney') && $c.util.getComponent('txt_dcSalesMoney').setValue) ? $c.util.getComponent('txt_dcSalesMoney').setValue($c.num.formatNumberKor(String(((($('#ipt_dcSales')[0]) && ($('#ipt_dcSales')[0]).getValue) ? ($('#ipt_dcSales')[0]).getValue() : (((($('#ipt_dcSales')[0]) && typeof ($('#ipt_dcSales')[0]).val === 'function') ? ($('#ipt_dcSales')[0]).val() : ((($('#ipt_dcSales')[0]) && ($('#ipt_dcSales')[0]).value !== undefined) ? ($('#ipt_dcSales')[0]).value : ($('#ipt_dcSales')[0]))))) == null ? '' : ((($('#ipt_dcSales')[0]) && ($('#ipt_dcSales')[0]).getValue) ? ($('#ipt_dcSales')[0]).getValue() : (((($('#ipt_dcSales')[0]) && typeof ($('#ipt_dcSales')[0]).val === 'function') ? ($('#ipt_dcSales')[0]).val() : ((($('#ipt_dcSales')[0]) && ($('#ipt_dcSales')[0]).value !== undefined) ? ($('#ipt_dcSales')[0]).value : ($('#ipt_dcSales')[0])))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'dc_sales_money'));
                    $c.num.formatNumber($('#ipt_dcSales')[0]);
                }
                $c.util.getComponent('cal_expDd').setValue($c.date.dateFormat(jsonData.exp_dd));
                $('#slc_currTpCd').find('option[value="' + jsonData.curr_tp_cd + '"]').attr("selected", true);
                $c.util.getComponent('ipt_brnNm').setValue(jsonData.brn_nm);
